MAX_RECURSION_DEPTH = 1000  # Limit recursion to prevent infinite loops


def mapo(relation, a, b, null_type=list, null_res=True, first=True, depth=0):
    """Apply a relation to corresponding elements in two sequences."""
    if depth > MAX_RECURSION_DEPTH:
        return fail  # Prevent infinite recursion

    if not isinstance(null_type, (type, type(None))) and not callable(null_type):
        raise ValueError("Invalid `null_type` provided.")

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    return conde(
        [nullo(a, b, default_ConsNull=null_type) if (null_res or not first) else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            Zzz(relation, a_car, b_car),
            Zzz(mapo, relation, a_cdr, b_cdr, null_type=null_type, first=False, depth=depth + 1),
        ],
    )


def map_anyo(relation, a, b, null_type=list, null_res=False, first=True, depth=0):
    """Apply a relation to corresponding elements in two sequences."""
    if depth > MAX_RECURSION_DEPTH:
        return fail  # Prevent infinite recursion

    if not isinstance(null_type, (type, type(None))) and not callable(null_type):
        raise ValueError("Invalid `null_type` provided.")

    b_car, b_cdr = var(), var()
    a_car, a_cdr = var(), var()

    # Ensure results are unique by filtering duplicates
    def unique_relation(a_car, b_car):
        return conde(
            [relation(a_car, b_car)],
            [eq(a_car, b_car)],  # Additional equality check for uniqueness
        )

    return conde(
        [nullo(a, b, default_ConsNull=null_type) if (null_res or first) else fail],
        [
            conso(a_car, a_cdr, a),
            conso(b_car, b_cdr, b),
            conde(
                [
                    Zzz(unique_relation, a_car, b_car),
                    Zzz(map_anyo, relation, a_cdr, b_cdr, null_type=null_type, depth=depth + 1),
                ],
                [
                    eq(a_car, b_car),
                    Zzz(map_anyo, relation, a_cdr, b_cdr, null_type=null_type, depth=depth + 1),
                ],
            ),
        ],
    )


def vararg_success(*args):
    """A dummy relation that always succeeds."""
    return succeed


def eq_length(u, v, default_ConsNull=list):
    """Construct a goal stating that two sequences are the same length and type."""
    return mapo(vararg_success, u, v, null_type=default_ConsNull)


def reduceo(relation, in_term, out_term, *args, **kwargs):
    """Relate a term to its reduced form."""
    def reduceo_goal(s):
        in_term_rf, out_term_rf = reify((in_term, out_term), s)

        # Base termination check
        if in_term_rf == out_term_rf:
            yield from succeed(s)

        term_rdcd = var()

        # Single application of the relation
        single_apply_g = relation(in_term_rf, term_rdcd, *args, **kwargs)

        # Recursive application of the relation
        recursive_g = reduceo(relation, term_rdcd, out_term_rf, *args, **kwargs)

        yield from lall(single_apply_g, conde([recursive_g], [eq(term_rdcd, out_term_rf)]))(s)

    return reduceo_goal


def walko(goal, graph_in, graph_out, rator_goal=None, null_type=etuple, map_rel=partial(map_anyo, null_res=True)):
    """Apply a binary relation between all nodes in two graphs."""
    def walko_goal(s):
        graph_in_rf, graph_out_rf = reify((graph_in, graph_out), s)

        rator_in, rands_in, rator_out, rands_out = var(), var(), var(), var()

        # Partial function for recursive calls
        _walko = partial(walko, goal, rator_goal=rator_goal, null_type=null_type, map_rel=map_rel)

        yield from conde(
            [goal(graph_in_rf, graph_out_rf)],
            [
                lall(
                    applyo(rator_in, rands_in, graph_in_rf),
                    applyo(rator_out, rands_out, graph_out_rf),
                    rator_goal(rator_in, rator_out),
                    map_rel(_walko, rands_in, rands_out, null_type=null_type),
                )
            ],
        )(s)

    return walko_goal


def term_walko(rator_goal, rands_goal, a, b, null_type=etuple, no_ident=False, **kwargs):
    """Walk through a term graph applying relational goals."""
    def term_walko_step(s, t):
        u, v = var(), var()
        w = var()

        yield from lall(
            ground_order((s, t), (u, v)),
            conde(
                [rator_goal(u)],
                [
                    Zzz(map_anyo, term_walko_step, u, w, null_type=null_type),
                    rands_goal(u, v),
                ],
            ),
        )(s)

    return conde([term_walko_step(a, b)], [eq(a, b)] if not no_ident else [])

